    recipient: 'жене Любови Андреевне',
    text: "Любочка! Победа! Война кончилась! Сегодня подписан акт о капитуляции Германии! Все плачут, все обнимаются, стреляют в воздух. Я стою и не верю — всё, кончилось. Три года, девять месяцев и один день. Люба, я живой, целый, скоро приеду домой. Жди меня, родная, я уже собираю вещи.",
