    text: "Дорогая! Давно не писал — жизнь в лесу не располагает. Перемещались по лесам, немцы ходят по следам. Сейчас остановились на привале, решил накатать несколько строк. Здоровье нормальное, с боеприпасами пока всё в порядке. Обнимаю всей душой, твой.",
