    text: "Верочка! Сегодня 24-я годовщина Октября. Встречали в бомбоубежище — немцы бомбят, но мы пели «Интернационал». Я работаю в госпитале санитаркой. Видела столько страшного... Но мальчишки держатся. Один без ноги просил передать письмо — написал его кровью на бинте. Я плакала, Верочка. Но мы победим. Обязательно победим.",
    context: 'Письмо из эвакогоспиталя. Дмитриева Мария Семёновна — медсестра, ноябрь 1941 года.',
    slug: 'dmitrieva-mariya-1941',
    images: ['/images/letters/letter-writing.jpg'],
