    text: "Серёга! Мы на «Коре» — это такой полуостров. Бои идут круглые сутки. Вчера немцы пошли в атаку — три раза за день. Отбили все, но потери есть. Мой сослуживец Коля, парень из Тулы, погиб. Прямо рядом со мной. Я его письмо матери отправлю. Серёг, береги себя. Если что — мои родители тебе как родные.",
