    recipient: 'сестре Галине',
    text: "Галочка! Я в Севастополе. Море видно из окна госпиталя — голубое, красивое, но над ним дым. Я медсестра теперь, перевязываю, уколы делаю. Мальчики приходят в сознание — первое, что просят: «Письмо маме напишите». Я пишу, Галочка, за всех. Руки дрожат, но пишу. Скоро приеду домой — обещаю.",
