    recipient: 'мужу Алексею',
    text: "Лёшенька, родной! Я на Урале, эвакуация. Работаю на заводе — танки собираю. Помнишь, как я жаловалась, что не умею гвоздь забить? А теперь броню креплю! Завод круглые сутки работает, смена за сменой. Сплю в бараке, холодно, но не жалуюсь. Главное — танки идут на фронт. Ты там береги себя. Я жду.",
