    text: "Андрюшка! Папа теперь на «Катюше». Машина грозная — стволы как жерди, залп — и полк немцев как не бывало. Вчера накрыли их скопление у переправы — горело всё. Но я думаю, Андрюш, что это не красиво. Это ужасно. Но они пришли на нашу землю. Папа защищает тебя, маму, бабушку. Расти умным. И мирным.",
