    text: "Мамуля! Два года войны. Я в медсанбате, работаю хирургом. Руки до локтей в крови, но спасаю. Вчера ампутировал ногу мальчишке — ему 19 лет. Он плакал, мам, а я с ним. Потом он сказал: «Доктор, я буду танкистом — без ноги можно в танке». Я заплакала. Люди невероятные, мам. Мы победим. Обязательно.",
