    text: "Танечка! Курская дуга. Идёт крупнейшее танковое сражение в истории. Сотни танков, грохот не прекращается. Вчера подбили «тигр» — мощная машина, но наша лучше. Я цел, не волнуйся. Но видел страшное: поле в горящих танках, как ад. Танечка, если что случится — знай, я любил тебя всей душой. Но ничего не случится. Я вернусь.",
