    text: "Оленька! Я на Дальнем Востоке — защищаем границу. Здесь тихо, но напряжённо. Я связист, сижу у аппарата, принимаю шифровки. Вчера перехватили японские переговоры — готовят что-то. Мы готовы. Оля, я скучаю по дому, по нашему саду, где малина. Но здесь красиво — горы, тайга. Приеду — покажу фотографии. Береги себя.",
