    recipient: 'мужу Сергею',
    text: "Серёжа, родной! Я в Киеве! Освободили! Шесть дней шли улицами, бои в каждом доме. Но мы вошли. Народ плачет от радости, целует солдат. Я видела, как старик украинец целовал землю — говорил: «Моя, родная». Серёжа, я плачу от счастья. Скоро и твой город освободят. Жди меня. Я уже собираю вещи.",
    context: 'Письмо из освобождённого Киева. Голубева Надежда Петровна — связистка, октябрь 1943 года.',
