    recipient: 'родителям',
    text: "Мам, пап! Последний день 1943 года. Я в госпитале в Ташкенте — ранена под Киевом. Нога заживает, врачи молодцы. Здесь тепло, фрукты, совсем не похоже на войну. Но я скучаю по снегу, по ёлке, по вам. Встречаю Новый год с соседкой по палате — она тоже из фронта. Поём песни, плачем, смеёмся. 1944-й будет победным!",
