    text: "Люда, родная! Мы в Литве. Леса, озёра — красиво, но война портит всё. Вчера освободили концлагерь — узники в лохмотьях, худые, как скелеты. Но глаза горят! Один еврей обнял меня, плакал: «Вы — ангелы». Нет, Люда, мы просто солдаты. Но мы их спасли. Это главное. Скоро дома. Жди. Люблю.",
