    text: "Папа! Я в Освенциме. Освободили. Ты не представляешь, что здесь было. Крематории, кости, детские игрушки. Я плакал, папа, как малый. Но мы их спасли — тех, кто ещё жив. Они в шоке, не верят. Один еврей сказал: «Я думал, Бог нас бросил». Нет, папа, мы пришли. Скоро дома. С Победой. И с болью.",
