    recipient: 'матери Даржите',
    text: "Аав, аав! (Мама, мама!) Победа! Война кончилась! Я живой! Три года воевал, мама, три года. Я видел Москву, Сталинград, Курск, Берлин. Теперь еду домой, в Калмыкию. Мама, я привезу тебе немецкий чайник — красивый, медный. И расскажу всё. Спасибо, что молилась. Спасибо, что ждала. Я вернулся. С Победой, аав!",
