    text: "Петенька! Папа в Германии, оккупация. Странно — мы победили, но работы много. Охраняем порядок, помогаем восстанавливать. Вчера немецкий мальчик дал мне яблоко — я не взял сначала, а он плакал. Взял. Пет, мы не звери. Мы победили, но остались людьми. Скоро домой. Привезу тебе немецкий велосипед — настоящий! Жди.",
