    recipient: 'жене Екатерине',
    text: "Катюша, родная! Мы на Воронежском фронте. Лето, жара, пыль. Немцы наступают, но мы держимся. Вчера был бой — мой сослуживец Коля, парень из Тулы, погиб. Прямо рядом со мной. Я его письмо матери отправлю. Катя, береги себя. Я делаю своё дело. Скоро война кончится, и я приеду. Жди меня. Люблю.",
