    recipient: 'мужу Петру',
    text: "Петенька, любимый! Я в Сталинграде. Город в огне, но мы стоим. Я медсестра — перевязываю, уколы делаю. Мальчики приходят в сознание — первое, что просят: «Письмо маме напишите». Я пишу, Петя, за всех. Руки дрожат, но пишу. Скоро приеду домой — обещаю. Ты береги себя. Живи, мой хороший.",
