    text: "Коля, любимый! Я в тылу, но не сиджу сложа руки. Организовала подпольную типографию — печатаем листовки. Вчера расклеили по всему городу: «Скоро придём!». Немцы бесились, но не поймали. Коля, я теперь партизанка. Ночами не сплю, сердце колотится, но я счастлива. Делаю своё дело. Ты береги себя на фронте. Скоро встретимся.",
