    text: "Любочка, зайка! Мама теперь командир взвода — зенитчица! Вчера сбили немецкий самолёт, горел как факел. Все девчонки кричали от радости. Я стреляла из пулемёта, руки дрожали, но попала! Люба, я теперь настоящий боец. Когда приедешь из эвакуации — расскажу всё. Горжусь собой. Целую крепко. Пришли фото — скучаю.",
    context: 'Письмо из зенитной части. Чернова Анна Васильевна — зенитчица, май 1943 года.',
    slug: 'chernova-anna-1943',
