    recipient: 'мужу Ивану',
    text: "Ванечка, родной! Я в Гомеле. Освободили Белоруссию! Леса, болота, партизаны — везде наши. Вчера встретила отряд — полгода не брились, в лохмотьях, но с пулемётами. Крепкие ребята. Мы вместе пошли на немецкий гарнизон — взяли за час. Ваня, я видела, как дети выбегали из леса — полгода в партизанах. Удивительные люди. Скоро дома.",
