    text: "Петенька! Последний день 1943 года. Папа в госпитале в Ташкенте — ранен под Киевом. Нога заживает, врачи молодцы. Здесь тепло, фрукты, совсем не похоже на войну. Но я скучаю по снегу, по ёлке, по тебе. Встречаю Новый год с соседом по палате — он тоже из фронта. Поём песни, плачем, смеёмся. 1944-й будет победным!",
