    recipient: 'брату Илье',
    text: "Илья! Папа теперь разведчик. Вчера пробрался в немецкий штаб — документы украл, карты. Сидел под окном три часа, пока офицеры спали. Адреналин, Илья! Но страшно было. Вернулся — командир обнял, медаль обещал. Иль, я делаю важное дело. Но хочу домой. К тебе и маме. Скоро, сынок. Скоро.",
