    text: "Алешенька, родной! Я в Крыму! Освобождали Севастополь — вошла в город, который ты защищал. Помнишь? Я шла по улицам, где ты ходил, смотрела на море, которое ты видел. Алеша, я плакала. Но гордилась. Теперь я здесь, защищаю. Скоро война кончится, и мы встретимся на этих улицах. Обещаю. Живи, мой хороший.",
