    text: "Оленька! Восточная Пруссия. Мороз -20, снег по пояс. Немцы сопротивляются ожесточённо — это их земля, они держатся. Вчера штурмовали деревню — каждый дом превращён в дзот. Оля, я устал. Но иду. Думаю о тебе, о нашем сыне. Он родился, а я не видел. Пришли фото — скучаю. Скоро дома. С Победой. Люблю.",
