    text: "Серёжа, родной! С Днём святого Валентина! Я в Берлине! Ну, почти — окраины. Артиллерия гремит, небо в огне. Но я счастлива — скоро кончится. Вчера видела колонну немцев с белыми флагами — сдаются! Серёжа, мы победили! Осталось немного. Ты береги себя на фронте. Скоро встретимся. Я уже мечтаю о нашей жизни. Люблю.",
